#!/bin/bash
sed -i 's/<i data-lucide="play" class="w-4 h-4 fill-white"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4 fill-white"><polygon points="6 3 20 12 6 21 6 3"\/><\/svg>/g' index.html
sed -i 's/<i data-lucide="pause" class="w-4 h-4 fill-white"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4 fill-white"><rect x="14" y="4" width="4" height="16" rx="1"\/><rect x="6" y="4" width="4" height="16" rx="1"\/><\/svg>/g' index.html
sed -i 's/<i data-lucide="skip-forward" class="w-4 h-4 fill-white"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4 fill-white"><polygon points="5 4 15 12 5 20 5 4"\/><line x1="19" x2="19" y1="5" y2="19"\/><\/svg>/g' index.html
sed -i 's/<i data-lucide="volume-2" class="w-4 h-4"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"\/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"\/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"\/><\/svg>/g' index.html
sed -i 's/<i data-lucide="maximize-2" class="w-3.5 h-3.5"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-3.5 h-3.5"><polyline points="15 3 21 3 21 9"\/><polyline points="9 21 3 21 3 15"\/><line x1="21" x2="14" y1="3" y2="10"\/><line x1="3" x2="10" y1="21" y2="14"\/><\/svg>/g' index.html
sed -i 's/<i data-lucide="check" class="w-2 h-2 text-white stroke-\[3\]"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-2 h-2 text-white stroke-[3]"><polyline points="20 6 9 17 4 12"\/><\/svg>/g' index.html
sed -i 's/<i data-lucide="more-horizontal" class="w-4 h-4 text-white"><\/i>/<svg xmlns="http:\/\/www.w3.org\/2000\/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4 text-white"><circle cx="12" cy="12" r="1"\/><circle cx="19" cy="12" r="1"\/><circle cx="5" cy="12" r="1"\/><\/svg>/g' index.html
